// Milestone 9 — Performance & stress smoke test.
//
// Drives a realistic sustained-load scenario against the real CHASE Studio Pro
// app and measures REAL runtime metrics: the FPS readout the engine publishes to
// the status bar, and the JS heap from performance.memory when the browser
// exposes it. Nothing here is faked or sleep-based — every number reported is
// sampled from the live page while the Babylon.js scene is under load.
//
// Stress scenario:
//   1. Import the three real GLB fixtures in tests/fixtures/ (generated by
//      tools/make-test-glb.mjs) multiple times to populate the scene with many
//      meshes/materials.
//   2. Cycle through every studio camera repeatedly (forces re-renders + view
//      changes), and exercise each quality profile (low/balanced/high).
//   3. Sample FPS + heap on a fixed cadence for a sustained window.
//
// Assertions:
//   - No page crash and no uncaught page errors.
//   - The engine reaches a ready state and publishes a numeric FPS readout.
//   - Median FPS stays above a sane floor (configurable; defaults tuned for
//     software-WebGL headless rendering, see PERFORMANCE_REPORT.md).
//
// Output: a metrics JSON log + a screenshot under docs/evidence/phase-9/.
// Exits non-zero on any failure.
//
// Booting: like the other tests/*.mjs smoke tests, this expects an app URL at
// CHASE_VISUAL_BASE_URL (defaults to http://127.0.0.1:1420). If no server is
// reachable there, it will build the app and start `vite preview` itself so the
// test is self-contained. Set CHASE_PERF_NO_SERVER=1 to skip the auto-boot and
// require an externally provided URL.

import { spawn } from 'node:child_process';
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';

const root = resolve(fileURLToPath(new URL('..', import.meta.url)));
const baseUrl = process.env.CHASE_VISUAL_BASE_URL ?? 'http://127.0.0.1:1420';
const evidenceDir = resolve(process.env.CHASE_PERF_EVIDENCE_DIR ?? resolve(root, 'docs/evidence/phase-9'));
mkdirSync(evidenceDir, { recursive: true });

// Tunables (all overridable via env so CI / faster boxes can tighten them).
const SAMPLE_INTERVAL_MS = Number(process.env.CHASE_PERF_SAMPLE_INTERVAL_MS ?? 500);
const STRESS_DURATION_MS = Number(process.env.CHASE_PERF_DURATION_MS ?? 20_000);
const IMPORT_ROUNDS = Number(process.env.CHASE_PERF_IMPORT_ROUNDS ?? 3);
// Floor for the median FPS. Software-WebGL (swiftshader) headless rendering is
// far slower than a real GPU, so the default floor is intentionally low; tighten
// via CHASE_PERF_MIN_FPS on GPU-backed runners.
const MIN_MEDIAN_FPS = Number(process.env.CHASE_PERF_MIN_FPS ?? 5);

const fixtures = [
  resolve(root, 'tests/fixtures/chase-test-cube.glb'),
  resolve(root, 'tests/fixtures/chase-test-pyramid.glb'),
  resolve(root, 'tests/fixtures/chase-test-octa.glb'),
];
const cameraIds = ['cam1', 'cam2', 'cam3', 'cam4', 'cam5', 'cam6'];
const qualityModes = ['low', 'balanced', 'high'];

function log(message) {
  console.log(`[perf-stress] ${message}`);
}

async function ensureFixtures() {
  const missing = fixtures.filter((file) => !existsSync(file));
  if (missing.length === 0) return;
  log(`generating ${missing.length} missing GLB fixture(s) via tools/make-test-glb.mjs`);
  await runCommand(process.execPath, [resolve(root, 'tools/make-test-glb.mjs')], { cwd: root });
  const stillMissing = fixtures.filter((file) => !existsSync(file));
  if (stillMissing.length) throw new Error(`GLB fixtures still missing after generation: ${stillMissing.join(', ')}`);
}

function runCommand(cmd, args, options) {
  return new Promise((resolvePromise, rejectPromise) => {
    const child = spawn(cmd, args, { stdio: 'inherit', ...options });
    child.on('error', rejectPromise);
    child.on('exit', (code) => (code === 0 ? resolvePromise() : rejectPromise(new Error(`${cmd} ${args.join(' ')} exited ${code}`))));
  });
}

async function isServerUp(url) {
  try {
    const res = await fetch(url, { method: 'GET' });
    return res.ok || res.status === 200;
  } catch {
    return false;
  }
}

async function waitForServer(url, timeoutMs) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (await isServerUp(url)) return true;
    await new Promise((r) => setTimeout(r, 1000));
  }
  return false;
}

// If nothing is listening at baseUrl, build the app and boot `vite preview`.
async function maybeStartServer() {
  if (process.env.CHASE_PERF_NO_SERVER === '1') {
    if (!(await isServerUp(baseUrl))) throw new Error(`CHASE_PERF_NO_SERVER=1 but no server reachable at ${baseUrl}`);
    return null;
  }
  if (await isServerUp(baseUrl)) {
    log(`reusing already-running server at ${baseUrl}`);
    return null;
  }
  log('no server reachable — building app (npm run build)…');
  await runCommand('npm', ['run', 'build'], { cwd: root });
  log('starting `vite preview` on port 1420…');
  const server = spawn('npm', ['run', 'preview', '--', '--port', '1420', '--strictPort'], {
    cwd: root,
    stdio: 'inherit',
    env: { ...process.env },
  });
  const ok = await waitForServer(baseUrl, 120_000);
  if (!ok) {
    server.kill('SIGTERM');
    throw new Error(`vite preview did not come up at ${baseUrl} within 120s`);
  }
  log(`preview server is up at ${baseUrl}`);
  return server;
}

function median(values) {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

// Reads the FPS the engine publishes to the status bar (rendered as "<n> fps"
// in the centered .mono span). Returns null when the engine has not yet reported.
async function readFps(page) {
  return page.evaluate(() => {
    const spans = Array.from(document.querySelectorAll('span'));
    for (const span of spans) {
      const text = span.textContent ?? '';
      const match = text.match(/(\d+(?:\.\d+)?)\s*fps/i);
      if (match) return Number(match[1]);
    }
    return null;
  });
}

async function readHeap(page) {
  return page.evaluate(() => {
    const mem = performance && performance.memory;
    if (!mem) return null;
    return {
      usedJSHeapMB: +(mem.usedJSHeapSize / (1024 * 1024)).toFixed(2),
      totalJSHeapMB: +(mem.totalJSHeapSize / (1024 * 1024)).toFixed(2),
      limitJSHeapMB: +(mem.jsHeapSizeLimit / (1024 * 1024)).toFixed(2),
    };
  });
}

async function main() {
  await ensureFixtures();
  const server = await maybeStartServer();

  const launchOptions = {
    headless: true,
    // Force software-backed WebGL (swiftshader via ANGLE) so Babylon.js can
    // render in headless environments without a real GPU. Override the whole
    // arg list with CHASE_CHROMIUM_ARGS (comma-separated) if needed.
    args: process.env.CHASE_CHROMIUM_ARGS
      ? process.env.CHASE_CHROMIUM_ARGS.split(',')
      : ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist'],
  };
  if (process.env.CHASE_CHROMIUM_EXECUTABLE) launchOptions.executablePath = process.env.CHASE_CHROMIUM_EXECUTABLE;

  const browser = await chromium.launch(launchOptions);
  // performance.memory is only exposed by Chromium under precise mode off; the
  // flag below maximizes the chance the heap readings are available.
  const context = await browser.newContext({ viewport: { width: 1440, height: 1000 } });
  const page = await context.newPage();

  const pageErrors = [];
  const consoleErrors = [];
  let crashed = false;
  page.on('pageerror', (error) => pageErrors.push(error.message));
  page.on('console', (msg) => {
    if (msg.type() === 'error') consoleErrors.push(msg.text());
  });
  page.on('crash', () => {
    crashed = true;
  });

  const samples = [];
  const startedAt = new Date().toISOString();
  let medianFps = 0;
  let outcome = 'pass';
  const stressLog = [];

  try {
    log(`navigating to ${baseUrl}`);
    await page.goto(baseUrl, { waitUntil: 'commit', timeout: 120_000 });
    await page.getByTestId('builder-surface').waitFor({ state: 'visible', timeout: 240_000 });

    // Wait for the engine to actually start reporting a numeric FPS.
    log('waiting for the engine to report a live FPS readout…');
    await page.waitForFunction(() => {
      const spans = Array.from(document.querySelectorAll('span'));
      return spans.some((span) => /(\d+(?:\.\d+)?)\s*fps/i.test(span.textContent ?? ''));
    }, undefined, { timeout: 120_000 });
    const firstFps = await readFps(page);
    if (firstFps === null) throw new Error('engine never published a numeric FPS readout');
    log(`engine ready; initial FPS readout = ${firstFps}`);

    // --- Stress: import the GLB fixtures repeatedly to load the scene up. ---
    const fileInput = page.getByTestId('asset-file-input');
    await page.getByTestId('asset-import-panel').waitFor({ state: 'visible', timeout: 30_000 });
    for (let round = 0; round < IMPORT_ROUNDS; round += 1) {
      await fileInput.setInputFiles(fixtures);
      // Confirm imports landed: the scene outliner should list assets.
      await page.waitForFunction(
        () => document.querySelectorAll('[data-testid^="outliner-asset-"]').length > 0,
        undefined,
        { timeout: 30_000 },
      );
      const assetCount = await page.locator('[data-testid^="outliner-asset-"]').count();
      stressLog.push(`import round ${round + 1}: ${assetCount} asset(s) in scene`);
      log(`import round ${round + 1}/${IMPORT_ROUNDS} — ${assetCount} asset(s) in scene`);
    }

    // --- Sustained sampling loop while cycling cameras + quality modes. ---
    log(`running sustained stress for ${STRESS_DURATION_MS} ms (sampling every ${SAMPLE_INTERVAL_MS} ms)…`);
    const deadline = Date.now() + STRESS_DURATION_MS;
    let tick = 0;
    while (Date.now() < deadline) {
      if (crashed) throw new Error('page crashed during stress run');

      // Switch camera (round-robin) via the real camera-strip thumbnails.
      const camId = cameraIds[tick % cameraIds.length];
      const thumb = page.getByTestId(`camera-thumb-${camId}`);
      if (await thumb.count()) {
        await thumb.click({ force: true, noWaitAfter: true }).catch(() => {});
      }

      // Every few ticks, change the quality profile to exercise re-init paths.
      if (tick % cameraIds.length === 0) {
        const mode = qualityModes[(tick / cameraIds.length) % qualityModes.length | 0];
        const qButton = page.getByRole('button', { name: new RegExp(`^${mode}$`, 'i') }).first();
        if (await qButton.count()) {
          await qButton.click({ force: true, noWaitAfter: true }).catch(() => {});
        }
      }

      const fps = await readFps(page);
      const heap = await readHeap(page);
      samples.push({
        t: Date.now() - (deadline - STRESS_DURATION_MS),
        camera: camId,
        fps,
        heap,
      });
      tick += 1;
      await new Promise((r) => setTimeout(r, SAMPLE_INTERVAL_MS));
    }

    const fpsValues = samples.map((s) => s.fps).filter((v) => typeof v === 'number');
    if (fpsValues.length === 0) throw new Error('no FPS samples captured during stress run');
    medianFps = median(fpsValues);
    const minFps = Math.min(...fpsValues);
    const maxFps = Math.max(...fpsValues);
    log(`FPS over ${fpsValues.length} samples — median ${medianFps}, min ${minFps}, max ${maxFps}`);

    const heapSamples = samples.map((s) => s.heap).filter(Boolean);
    if (heapSamples.length) {
      const firstHeap = heapSamples[0].usedJSHeapMB;
      const lastHeap = heapSamples[heapSamples.length - 1].usedJSHeapMB;
      log(`JS heap (used) — start ${firstHeap} MB, end ${lastHeap} MB (Δ ${(lastHeap - firstHeap).toFixed(2)} MB)`);
    } else {
      log('performance.memory not exposed by this browser — heap readings unavailable (this is expected on non-Chromium/strict builds)');
    }

    // Screenshot the loaded, stressed scene as evidence.
    await page.screenshot({ path: resolve(evidenceDir, 'perf-stress-builder.png'), fullPage: true });

    if (crashed) throw new Error('page crashed during stress run');
    if (pageErrors.length) throw new Error(`uncaught page errors during stress run: ${pageErrors.join(' | ')}`);
    if (medianFps < MIN_MEDIAN_FPS) {
      throw new Error(`median FPS ${medianFps} fell below floor ${MIN_MEDIAN_FPS}`);
    }
  } catch (error) {
    outcome = 'fail';
    var failure = error;
  } finally {
    const fpsValues = samples.map((s) => s.fps).filter((v) => typeof v === 'number');
    const heapSamples = samples.map((s) => s.heap).filter(Boolean);
    const metrics = {
      outcome,
      startedAt,
      finishedAt: new Date().toISOString(),
      baseUrl,
      config: { SAMPLE_INTERVAL_MS, STRESS_DURATION_MS, IMPORT_ROUNDS, MIN_MEDIAN_FPS },
      chromiumArgs: launchOptions.args,
      stressLog,
      sampleCount: samples.length,
      fps: fpsValues.length
        ? {
            median: median(fpsValues),
            min: Math.min(...fpsValues),
            max: Math.max(...fpsValues),
            mean: +(fpsValues.reduce((a, b) => a + b, 0) / fpsValues.length).toFixed(2),
          }
        : null,
      heap: heapSamples.length
        ? {
            available: true,
            startUsedMB: heapSamples[0].usedJSHeapMB,
            endUsedMB: heapSamples[heapSamples.length - 1].usedJSHeapMB,
            peakUsedMB: Math.max(...heapSamples.map((h) => h.usedJSHeapMB)),
            limitMB: heapSamples[heapSamples.length - 1].limitJSHeapMB,
          }
        : { available: false, note: 'performance.memory not exposed in this environment' },
      pageErrors,
      consoleErrors,
      crashed,
      samples,
    };
    const metricsPath = resolve(evidenceDir, 'perf-stress-metrics.json');
    writeFileSync(metricsPath, JSON.stringify(metrics, null, 2));
    log(`metrics log written to ${metricsPath}`);

    await context.close().catch(() => {});
    await browser.close().catch(() => {});
    if (server) {
      server.kill('SIGTERM');
    }
  }

  if (outcome === 'fail') {
    console.error('perf-stress smoke failed');
    console.error(failure);
    process.exit(1);
  }
  console.log('perf-stress smoke passed');
  console.log(`median FPS ${medianFps} over ${samples.length} samples; evidence written to ${evidenceDir}`);
}

main().catch((error) => {
  console.error('perf-stress smoke failed');
  console.error(error);
  process.exit(1);
});
